-- Phase 6: Services and Local Resolution Network. Additive to schemas v131-v136.
CREATE TABLE IF NOT EXISTS merchant_branches(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,branch_code TEXT,name TEXT NOT NULL,address_line TEXT NOT NULL,postal_code TEXT,city TEXT NOT NULL,country_code TEXT NOT NULL,phone TEXT,public_email TEXT,latitude REAL,longitude REAL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_catalog(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,category TEXT,description TEXT,default_duration_minutes INTEGER,delivery_mode TEXT NOT NULL DEFAULT 'onsite',recurring_allowed INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_engagements(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,organization_id TEXT NOT NULL,service_id TEXT NOT NULL,customer_email TEXT,customer_name TEXT,branch_id TEXT,assigned_member_id TEXT,resource_id TEXT,status TEXT NOT NULL DEFAULT 'booked',scheduled_start TEXT,scheduled_end TEXT,actual_start TEXT,actual_end TEXT,location_text TEXT,reference TEXT,price_amount REAL,currency TEXT,notes TEXT,recurrence_rule TEXT,parent_engagement_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_network_providers(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,provider_type TEXT NOT NULL,professional_profile_id TEXT UNIQUE,organization_id TEXT UNIQUE,display_name TEXT NOT NULL,description TEXT,coarse_location TEXT,accepting_requests INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_network_capabilities(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,provider_id TEXT NOT NULL,capability_key TEXT NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL,service_modes_json TEXT NOT NULL DEFAULT '[]',pricing_model TEXT NOT NULL DEFAULT 'QUOTE_REQUIRED',starting_price_cents INTEGER,currency TEXT NOT NULL DEFAULT 'EUR',coverage_type TEXT NOT NULL DEFAULT 'REMOTE',coverage_json TEXT NOT NULL DEFAULT '{}',brand_compatibility_json TEXT NOT NULL DEFAULT '[]',description TEXT,active INTEGER NOT NULL DEFAULT 1,declaration_status TEXT NOT NULL DEFAULT 'PROVIDER_DECLARED',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(provider_id,capability_key));
CREATE TABLE IF NOT EXISTS service_network_availability(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,provider_id TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OFFERED',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_network_briefs(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,need_id TEXT NOT NULL UNIQUE,buyer_account_id TEXT NOT NULL,thing_passport_id TEXT,title TEXT NOT NULL,issue_description TEXT NOT NULL,category TEXT NOT NULL,service_mode TEXT NOT NULL,coarse_location TEXT,brand TEXT,model TEXT,desired_window_start TEXT,desired_window_end TEXT,address_required INTEGER NOT NULL DEFAULT 0,approved_fields_json TEXT NOT NULL DEFAULT '[]',confirmed_at TEXT,matching_enabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_network_addresses(brief_id TEXT PRIMARY KEY,buyer_account_id TEXT NOT NULL,address_line TEXT NOT NULL,postal_code TEXT,city TEXT NOT NULL,country_code TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_network_brief_attachments(id TEXT PRIMARY KEY,brief_id TEXT NOT NULL,document_id TEXT NOT NULL,approved_at TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(brief_id,document_id));
CREATE TABLE IF NOT EXISTS service_network_matches(id TEXT PRIMARY KEY,brief_id TEXT NOT NULL,provider_id TEXT NOT NULL,capability_id TEXT NOT NULL,match_score INTEGER NOT NULL,reasons_json TEXT NOT NULL DEFAULT '[]',failed_constraints_json TEXT NOT NULL DEFAULT '[]',generated_at TEXT NOT NULL,UNIQUE(brief_id,provider_id,capability_id));
CREATE TABLE IF NOT EXISTS service_network_invites(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,buyer_account_id TEXT NOT NULL,brief_id TEXT NOT NULL,contact TEXT NOT NULL,invitation_note TEXT,status TEXT NOT NULL DEFAULT 'SENT',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_network_quote_requests(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,brief_id TEXT NOT NULL,provider_id TEXT NOT NULL,capability_id TEXT NOT NULL,buyer_account_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'SENT',diagnostic_first INTEGER NOT NULL DEFAULT 0,message TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(brief_id,provider_id,capability_id));
CREATE TABLE IF NOT EXISTS service_network_quotes(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,quote_request_id TEXT NOT NULL,provider_id TEXT NOT NULL,buyer_account_id TEXT NOT NULL,amount_cents INTEGER,currency TEXT NOT NULL DEFAULT 'EUR',pricing_type TEXT NOT NULL DEFAULT 'FIXED',diagnostic_fee_cents INTEGER,scope TEXT NOT NULL,estimated_duration_minutes INTEGER,valid_until TEXT,status TEXT NOT NULL DEFAULT 'SENT',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_network_bookings(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,brief_id TEXT NOT NULL,provider_id TEXT NOT NULL,capability_id TEXT NOT NULL,quote_id TEXT,buyer_account_id TEXT NOT NULL,availability_id TEXT,service_mode TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'REQUESTED',scheduled_start TEXT,scheduled_end TEXT,provider_note TEXT,client_note TEXT,payment_mode TEXT NOT NULL DEFAULT 'EXTERNAL_MANUAL',payment_status TEXT NOT NULL DEFAULT 'NOT_RECORDED',started_at TEXT,completed_at TEXT,cancelled_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_network_booking_messages(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,booking_id TEXT NOT NULL,actor_type TEXT NOT NULL,actor_buyer_account_id TEXT,actor_organization_id TEXT,body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_network_booking_attachments(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL,document_id TEXT NOT NULL,added_by_buyer_account_id TEXT,approved_for_provider_at TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(booking_id,document_id));
CREATE TABLE IF NOT EXISTS service_network_reports(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,booking_id TEXT NOT NULL UNIQUE,provider_id TEXT NOT NULL,summary TEXT NOT NULL,work_performed TEXT NOT NULL,diagnosis TEXT,recommendations TEXT,service_warranty_days INTEGER,warranty_terms TEXT,status TEXT NOT NULL DEFAULT 'SUBMITTED',submitted_at TEXT NOT NULL,confirmed_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_network_report_parts(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,report_id TEXT NOT NULL,name TEXT NOT NULL,part_number TEXT,quantity INTEGER NOT NULL DEFAULT 1,unit_cost_cents INTEGER,currency TEXT NOT NULL DEFAULT 'EUR',notes TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_network_favorites(buyer_account_id TEXT NOT NULL,provider_id TEXT NOT NULL,source_booking_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(buyer_account_id,provider_id));
CREATE TABLE IF NOT EXISTS service_network_events(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,booking_id TEXT,brief_id TEXT,provider_id TEXT,actor_type TEXT NOT NULL,event_type TEXT NOT NULL,details_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_service_provider_discovery ON service_network_providers(active,accepting_requests,updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_service_capability_match ON service_network_capabilities(category,active,provider_id);
CREATE INDEX IF NOT EXISTS idx_service_availability_provider ON service_network_availability(provider_id,status,starts_at);
CREATE INDEX IF NOT EXISTS idx_service_quote_provider ON service_network_quote_requests(provider_id,status,updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_service_booking_client ON service_network_bookings(buyer_account_id,status,updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_service_booking_provider ON service_network_bookings(provider_id,status,updated_at DESC);
